def solve_alpha_for_budget(r_base_arr, target_budget, mask, dt=DT, alpha_min=0.2, alpha_max=2.5, tol=1e-4, max_iter=50):
    """Solves alpha such that sum(max(0, alpha * r_base)[mask]) * dt == target_budget using bisection."""
    r_sub = r_base_arr[mask]
    # Check bounds
    r_lo = np.sum(np.maximum(alpha_min * r_sub, 0.0)) * dt
    r_hi = np.sum(np.maximum(alpha_max * r_sub, 0.0)) * dt
    if target_budget <= r_lo:
        return alpha_min
    if target_budget >= r_hi:
        return alpha_max

    lo, hi = alpha_min, alpha_max
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        r_mid = np.sum(np.maximum(mid * r_sub, 0.0)) * dt
        err = (r_mid - target_budget) / target_budget
        if abs(err) < tol:
            return mid
        if r_mid < target_budget:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

